// useStoreProjector (#2498) — wiring test: every scoped domain publishes from the live store
// while the relay runs, and the whole projector is dark when it doesn't. The payload SHAPES are
// pinned by the pure selector tests (lib/storeProjections.test.ts); this guards the mount-once
// hook actually feeds them and stays gated on tunnelRunning.
import { describe, it, expect, vi, beforeEach } from "vitest";
import { renderHook, act } from "@testing-library/react";
import { useAppStore } from "@/store";

vi.mock("@/features/tunnel/lib/tunnelDomains", () => ({
  publishTunnelDomain: vi.fn(),
  resetTunnelDomains: vi.fn(),
}));
vi.mock("@/features/tunnel/lib/alertHub", () => ({
  recordTunnelAlerts: vi.fn(),
  seedTunnelAlerts: vi.fn(),
}));
// The glance data hooks poll GitHub/errordb/plan.db — inert STABLE fixtures here (fresh arrays
// each render would re-fire the glance effect); their behavior is the glance feature's tests.
vi.mock("@/features/glance", () => {
  const projects = [{ id: "demo", name: "Demo", role: "service", health: "off", activity: "building" }];
  const faults = { demo: { level: "error", title: "boom", count: 2 } };
  return {
    useGlanceProjects: () => projects,
    useGlanceFaults: () => faults,
    useProjectFleet: () => null,
  };
});
vi.mock("@/features/designs", async (orig) => ({
  ...(await orig<Record<string, unknown>>()),
  // Observed, not exercised: the real hook tails a log through the bsc bridge. What this file is
  // asserting is the GATE — which is a decision the projector makes, not behaviour of the poll.
  useUiActivity: vi.fn(),
}));
vi.mock("@/features/skills", () => ({
  loadPendingLessons: vi.fn().mockResolvedValue([]),
}));
vi.mock("@/features/mcp", () => ({
  resolveAllInstalledMcp: (servers: { id: string }[]) => servers,
}));
vi.mock("@/shared/lib/fleet/useCoordLog", () => ({
  readCoordState: vi.fn().mockResolvedValue(null),
}));
// The security audit poll reads the audit log; stub it (preserving the module's
// other exports the store uses) so the poll is deterministic — profiles/assignments publish on mount.
vi.mock("@/shared/lib/core/bsc", async (orig) => ({
  ...(await orig<typeof import("@/shared/lib/core/bsc")>()),
  bscJson: vi.fn().mockResolvedValue([]),
}));

import { useStoreProjector } from "@/features/tunnel/useStoreProjector";
import { publishTunnelDomain, resetTunnelDomains } from "@/features/tunnel/lib/tunnelDomains";
import { useUiActivity } from "@/features/designs";

const publishedDomains = () =>
  new Set(vi.mocked(publishTunnelDomain).mock.calls.map(([domain]) => domain));

describe("useStoreProjector", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    useAppStore.setState({ tunnelRunning: false });
  });

  it("is dark while the relay is down", () => {
    renderHook(() => useStoreProjector());
    expect(publishTunnelDomain).not.toHaveBeenCalled();
  });

  it("publishes every store-resident domain once the relay runs", () => {
    useAppStore.setState({ tunnelRunning: true });
    renderHook(() => useStoreProjector());
    // `plan` is planner-published (usePlannerTunnelSync) and `alerts` flows through the hub —
    // everything else projects straight from the store on mount (security too — its audit poll
    // enriches later, but profiles/assignments publish immediately, #2530).
    expect(publishedDomains()).toEqual(new Set([
      "glance", "org", "blueprints", "skills", "components", "themes", "automations", "mcp", "security",
    ]));
    expect(resetTunnelDomains).toHaveBeenCalledTimes(1); // fresh run → re-send cache cleared
  });

  it("feeds the glance domain the same merged project/fault sources the desktop reads", () => {
    // The drill is keyed BY TAB now (`each-glance-tab-owns-its-own-drill`); mobile mirrors the
    // ACTIVE tab's depth, so an empty map is "no tab is drilled".
    useAppStore.setState({ tunnelRunning: true, glanceDrill: {} });
    renderHook(() => useStoreProjector());
    const glance = vi.mocked(publishTunnelDomain).mock.calls.find(([d]) => d === "glance")?.[1];
    expect(glance).toMatchObject({
      projects: [{ id: "demo", health: "error", reason: "boom", faults: 2 }],
      drill: null,
      drillFleet: null,
    });
  });

  it("re-publishes a domain when its store slice changes", () => {
    useAppStore.setState({ tunnelRunning: true });
    renderHook(() => useStoreProjector());
    vi.mocked(publishTunnelDomain).mockClear();
    // Braced body (#2515): persist makes setState return a Promise; leaking it into act defers
    // the projector effect past the assertion (see useNavHistory.test.tsx).
    act(() => { useAppStore.setState({ kitTheme: "contrast" }); });
    expect(publishedDomains()).toEqual(new Set(["themes"]));
  });

  // ── the phone is a first-class reason to re-hydrate ──────────────────────────────────────────
  //
  // A `bsc ui set` lands as a `ui-touch` line and NOTHING else — the desktop `setComponent`
  // fan-out never runs for a CLI edit. Until something tails that log the store keeps its
  // reference, so the effects above never fire and the phone never learns. The only tailer was
  // the Design Studio, gated on being the visible page, which meant authoring a spec from any
  // other workspace reached a paired phone never.

  it("tails the designer activity log while the tunnel is up and the Studio is not showing", () => {
    useAppStore.setState({ tunnelRunning: true, activeWorkspace: "glance" });
    renderHook(() => useStoreProjector());
    expect(useUiActivity).toHaveBeenCalledWith(true);
  });

  it("yields the tail to the Studio when the Studio is showing — never two pollers", () => {
    // Two active pollers would each keep their own cursor and push every touch into the activity
    // ring TWICE. The gate is split, not widened, so the union is covered with no overlap.
    useAppStore.setState({ tunnelRunning: true, activeWorkspace: "components" });
    renderHook(() => useStoreProjector());
    expect(useUiActivity).toHaveBeenCalledWith(false);
  });

  it("does not tail at all while the relay is down", () => {
    useAppStore.setState({ tunnelRunning: false, activeWorkspace: "glance" });
    renderHook(() => useStoreProjector());
    expect(useUiActivity).toHaveBeenCalledWith(false);
  });

  // ── absence is a CLAIM on this wire ──────────────────────────────────────────────────────────

  it("withholds the components domain while the records are still the lite boot projection", () => {
    // Boot paints from `bsc ui list --graph` (33 KB) before the 1.72 MB full read lands, and that
    // projection carries no `spec`. Publishing it would tell the phone every component is
    // spec-less — indistinguishable from "no spec authored", so it would fall back to bundled
    // baselines for all of them and then flip when phase 2 arrived.
    useAppStore.setState({
      tunnelRunning: true,
      components: [{ id: "c1", name: "Button", kitId: "react-ui", role: "primitive", lite: true }],
    } as never);
    renderHook(() => useStoreProjector());
    expect(publishedDomains()).not.toContain("components");
    // …and the rest of the projection is unaffected — this withholds ONE domain, not the mirror.
    expect(publishedDomains()).toContain("themes");
  });

  it("publishes components once the full records are in hand", () => {
    useAppStore.setState({
      tunnelRunning: true,
      components: [{ id: "c1", name: "Button", kitId: "react-ui", role: "primitive" }],
    } as never);
    renderHook(() => useStoreProjector());
    expect(publishedDomains()).toContain("components");
  });
});

